using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using Comfort.Common;
using EFT;
using EFT.InventoryLogic;
using UnityEngine;
namespace LocalSpt5Esp;
internal static class LoadoutPlans {
 internal sealed record Kit(string Name,List<ItemSpawner.SavedPreset> Items);
 static List<Kit> kits=new();static bool loaded,corrupt;static string name="",status="";static Vector2 scroll;static Task<string>? request;
 static readonly HashSet<string> chosen=new();
 static string FilePath=>Path.Combine(BepInEx.Paths.PluginPath,"LocalSpt5ESP","loadout-plans.json");
 static void Load(){if(loaded)return;loaded=true;try{kits=PresetStorage.Load<Kit>(FilePath);}catch(Exception e){corrupt=true;status="装备方案读取失败，原文件保留："+e.Message;}}
 static void Save(List<ItemSpawner.SavedPreset> items){if(corrupt)throw new ArgumentException("请先修复方案文件。");string title=name.Trim();if(title.Length is <1 or >80)throw new ArgumentException("请输入 1～80 字的方案名称。");if(items.Count==0)throw new ArgumentException("请选择物品标签，或装备物品后再保存。");var updated=kits.Where(k=>!k.Name.Equals(title,StringComparison.OrdinalIgnoreCase)).Append(new Kit(title,items)).ToList();PresetStorage.Save(FilePath,updated);kits=updated;status="已保存整套装备："+title;}
 internal static ItemComponentParameters Parameters(Item item){var p=new ItemComponentParameters{FoundInRaid=item.SpawnedInSession};var repair=item.GetItemComponent<RepairableComponent>();if(repair!=null){p.Durability=repair.Durability;p.MaxDurability=repair.MaxDurability;}var med=item.GetItemComponent<MedKitComponent>();if(med!=null&&med.MaxHpResource>0)p.MedicalResource=med.HpResource;var food=item.GetItemComponent<FoodDrinkComponent>();if(food!=null&&food.MaxResource>0)p.FoodResource=food.HpPercent;var key=item.GetItemComponent<KeyComponent>();if(key!=null&&key.Template.MaximumNumberOfUsage>0)p.KeyRemaining=Math.Max(0,key.Template.MaximumNumberOfUsage-key.NumberOfUsages);var poison=item.GetItemComponent<SideEffectComponent>();if(poison!=null)p.PoisonUses=poison.Value;var resource=item.GetItemComponent<ResourceComponent>();if(resource!=null)p.Resource=resource.Value;var kit=item.GetItemComponent<RepairKitComponent>();if(kit!=null)p.RepairKitResource=kit.Resource;var toggle=item.GetItemComponent<TogglableComponent>()??item.GetItemComponent<NightVisionComponent>()?.Togglable;if(toggle!=null)p.ToggledOn=toggle.On;return p;}
 static ItemAttachmentNode Capture(Item item,HashSet<IntPtr> seen,int depth=0){if(depth>12||!seen.Add(item.Pointer))throw new ArgumentException("装备附件结构存在循环或层级过深。");var node=new ItemAttachmentNode{Template=item.StringTemplateId,Parameters=Parameters(item)};var compound=item.TryCast<CompoundItem>();if(compound?.Slots!=null)foreach(var slot in compound.Slots)if(slot?.ContainedItem is Item child)node.Children[slot.ID]=Capture(child,seen,depth+1);var weapon=item.TryCast<Weapon>();if(weapon?.Chambers!=null)foreach(var slot in weapon.Chambers)if(slot?.ContainedItem is Item child&&!node.Children.ContainsKey(slot.ID))node.Children[slot.ID]=Capture(child,seen,depth+1);var magazine=item.TryCast<Magazine>();if(magazine?.Cartridges!=null)foreach(var cartridge in magazine.Cartridges.Items)if(cartridge!=null)node.Cartridges.Add(new(cartridge.StringTemplateId,Math.Max(1,cartridge.StackObjectsCount),Parameters(cartridge)));return node;}
 internal static ItemAttachmentNode CaptureItem(Item item)=>Capture(item,new());
 static List<ItemSpawner.SavedPreset> CaptureEquipment(){var player=Singleton<GameWorld>.Instance?.MainPlayer;var equipment=player?.Profile?.Inventory?.Equipment??throw new ArgumentException("进入战局或藏身处后可保存当前穿戴。");var result=new List<ItemSpawner.SavedPreset>();var seen=new HashSet<IntPtr>();
  void Add(Item item){if(!seen.Add(item.Pointer))return;var node=Capture(item,new());var values=new ItemSpawner.Values(false,0,0,false,0,false,0,false,0,false,0,"",0,node.Parameters);result.Add(new(Guid.NewGuid().ToString("N"),LootDisplay.ItemName(item,false),item.StringTemplateId,Math.Max(1,item.StackObjectsCount),values,node));var compound=item.TryCast<CompoundItem>();if(compound?.Grids!=null)foreach(var grid in compound.Grids)foreach(var content in grid.Items)if(content!=null)Add(content);}
  foreach(var slot in equipment.Slots){if(slot==null||slot.ID is "SecuredContainer" or "Scabbard" or "Dogtag")continue;var item=slot.ContainedItem;if(item==null)continue;if(slot.ID=="Pockets"){var pockets=item.TryCast<CompoundItem>();if(pockets?.Grids!=null)foreach(var grid in pockets.Grids)foreach(var child in grid.Items)if(child!=null)Add(child);}else Add(item);}
  return result;
 }
 static void Generate(Kit kit,bool missingOnly){try{if(request!=null)return;var inventory=Singleton<GameWorld>.Instance?.MainPlayer?.Profile;Dictionary<string,long> counts=new();if(missingOnly){if(inventory==null)throw new ArgumentException("进入战局或藏身处后才能读取现有物资并补齐。");counts=TaskNeeds.InventoryCounts(inventory);}var wanted=new List<(ItemSpawner.SavedPreset Preset,int Count)>();foreach(var item in kit.Items){int amount=item.Count;if(missingOnly){counts.TryGetValue(item.Template,out long held);int used=(int)Math.Min(held,amount);amount-=used;counts[item.Template]=held-used;}if(amount>0)wanted.Add((item,amount));}if(wanted.Count==0){status="现有物资已满足此方案。";return;}
  var mail=new List<Dictionary<string,object?>>();int prefix=0;foreach(var entry in wanted){string tag="kit"+prefix+++"_";var parts=ItemSpawner.PresetMail(entry.Preset,entry.Count);foreach(var part in parts){part["ref"]=tag+part["ref"];if(part.TryGetValue("parent",out var parent)&&parent!=null)part["parent"]=tag+parent;mail.Add(part);}}if(mail.Count>100)throw new ArgumentException("整套装备含附件与弹药超过 100 条，请拆分方案。");
  if(!ItemSpawner.InRaid()){request=GearMailClient.Send(mail,true);status="正在整套发送邮件…";return;}var results=new List<string>();foreach(var entry in wanted){var message=ItemSpawner.SpawnPreset(entry.Preset,entry.Count);results.Add(entry.Preset.Name+"："+message);if(!message.StartsWith("已添加",StringComparison.Ordinal))break;}status=string.Join("；",results);Plugin.Self.Log.LogInfo("Loadout plan result: "+status);
 }catch(Exception e){status=e.Message;}}
 internal static void Draw(Rect rect){Load();if(request?.IsCompleted==true){status=request.GetAwaiter().GetResult();request=null;}InterfaceMenu.Label(new Rect(rect.x,rect.y,rect.width,28),"整套装备方案",InterfaceMenu.Accent,18);InterfaceMenu.Paragraph(new Rect(rect.x,rect.y+36,rect.width,54),"勾选快捷物品标签组成一套，或保存当前穿戴。保留附件、弹匣混装与物品参数；背包内物资单独生成，补齐按模板数量计算。",null,12);name=InterfaceMenu.Field(new Rect(rect.x,rect.y+98,Math.Max(100,rect.width-332),31),name);if(InterfaceMenu.Button(new Rect(rect.xMax-320,rect.y+98,154,31),"保存勾选的标签"))try{Save(ItemSpawner.SavedPresets().Where(p=>chosen.Contains(p.Id)).ToList());}catch(Exception e){status=e.Message;}if(InterfaceMenu.Button(new Rect(rect.xMax-154,rect.y+98,154,31),"保存当前穿戴"))try{Save(CaptureEquipment());}catch(Exception e){status=e.Message;}
  var labels=ItemSpawner.SavedPresets();var view=new Rect(rect.x,rect.y+146,rect.width,Math.Max(70,rect.height-246));float tagsHeight=labels.Count*41+40,total=tagsHeight+kits.Count*96;scroll=GUI.BeginScrollView(view,scroll,new Rect(0,0,view.width-18,Math.Max(70,total)));InterfaceMenu.Label(new Rect(0,0,view.width-24,28),"选用快捷标签",InterfaceMenu.Accent,14);for(int i=0;i<labels.Count;i++){var label=labels[i];if(InterfaceMenu.Button(new Rect(0,35+i*41,view.width-24,33),(chosen.Contains(label.Id)?"✓  ":"＋  ")+label.Name+" ×"+label.Count,chosen.Contains(label.Id))){if(!chosen.Remove(label.Id))chosen.Add(label.Id);}}
  Kit? remove=null;for(int i=0;i<kits.Count;i++){var kit=kits[i];float y=tagsHeight+i*96;InterfaceMenu.Surface(new Rect(0,y,view.width-24,85),new Color(1,1,1,.035f),9);InterfaceMenu.Paragraph(new Rect(12,y+10,view.width-360,70),kit.Name+"\n"+kit.Items.Count+" 组物品",null,14);if(InterfaceMenu.Button(new Rect(view.width-340,y+20,94,32),request==null?"整套生成":"发送中…")&&request==null)Generate(kit,false);if(InterfaceMenu.Button(new Rect(view.width-238,y+20,94,32),"补齐缺少")&&request==null)Generate(kit,true);if(InterfaceMenu.Button(new Rect(view.width-136,y+20,104,32),"删除方案"))remove=kit;}GUI.EndScrollView();if(remove!=null)try{var updated=kits.Where(k=>k!=remove).ToList();PresetStorage.Save(FilePath,updated);kits=updated;status="装备方案已删除。";}catch(Exception e){status=e.Message;}
  InterfaceMenu.Paragraph(new Rect(rect.x,rect.yMax-86,rect.width,80),status+"\n战局内添加到背包，空间不足时可能部分添加；战局外发送邮件。",null,12);
 }
}
